const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',box:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5Zm0 9 9-4M12 12 3 8m9 4v10M7 5.7l9 5"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5Zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',cart:'<path d="M3 3h2l3 12h10l3-9H6M9 20h.01M18 20h.01"/><circle cx="9" cy="20" r="1"/><circle cx="18" cy="20" r="1"/>',swap:'<path d="M3 7h17m-4-4 4 4-4 4M21 17H4m4-4-4 4 4 4"/>',waste:'<path d="m12 3 10 18H2L12 3Zm0 6v5m0 3v1"/>',warehouse:'<path d="m3 8 9-5 9 5v13H3V8Zm4 13V11h10v10M7 15h10M7 18h10"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-17a3 3 0 0 1 0 6m2 4c3 1 3 3 3 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.box}</svg>`;
const nav=[['overview','grid','Resumen'],['inventory','box','Inventario'],['lots','layers','Lotes y trazabilidad'],['purchases','cart','Órdenes de compra'],['movements','swap','Movimientos'],['waste','waste','Mermas'],['suppliers','users','Proveedores'],['warehouses','warehouse','Almacenes']];
const inventory=[{id:1,name:'Resina epóxica industrial',sku:'INS-001',kind:'Insumo',lot:'LT-2026-084',qty:480,unit:'kg',warehouse:'Almacén central',expiry:'2026-09-25',cost:145,min:100,supplier:'Polímeros del Centro'},{id:2,name:'Perfil de aluminio 6063',sku:'INS-002',kind:'Insumo',lot:'LT-2026-078',qty:1250,unit:'pzas',warehouse:'Almacén central',expiry:null,cost:85,min:200,supplier:'Metales del Norte'},{id:3,name:'Soporte modular N-40',sku:'PT-001',kind:'Producto terminado',lot:'LT-2026-091',qty:320,unit:'pzas',warehouse:'Producto terminado',expiry:null,cost:240,min:80,supplier:'Producción interna'},{id:4,name:'Adhesivo estructural A2',sku:'INS-003',kind:'Insumo',lot:'LT-2026-065',qty:24,unit:'L',warehouse:'Almacén central',expiry:'2026-09-22',cost:310,min:50,supplier:'Química Industrial MX'},{id:5,name:'Panel compuesto 60 × 120',sku:'PT-002',kind:'Producto terminado',lot:'LT-2026-089',qty:180,unit:'pzas',warehouse:'Producto terminado',expiry:null,cost:420,min:40,supplier:'Producción interna'},{id:6,name:'Pintura electrostática negra',sku:'INS-004',kind:'Insumo',lot:'LT-2026-082',qty:85,unit:'kg',warehouse:'Taller de producción',expiry:'2027-03-12',cost:195,min:30,supplier:'Acabados Profesionales'}];
let movements=[{type:'Entrada',item:1,qty:120,date:'18 sep, 09:42',ref:'OC-2026-042',reason:'Recepción de compra'},{type:'Salida',item:3,qty:40,date:'18 sep, 09:15',ref:'DES-2026-018',reason:'Entrega a cliente'},{type:'Entrada',item:5,qty:60,date:'17 sep, 16:30',ref:'PROD-2026-012',reason:'Producción terminada'}];
let wastes=[{item:1,qty:8,cause:'Derrame',date:'17 sep 2026',note:'Pérdida durante trasvase'},{item:6,qty:3,cause:'Daño de empaque',date:'15 sep 2026',note:'Saco perforado en almacenamiento'}];
const purchases=[{id:'OC-2026-042',supplier:'Polímeros del Centro',date:'18 sep 2026',amount:87000,status:'Recepción parcial',item:'Resina epóxica industrial',ordered:'600 kg',received:'120 kg'},{id:'OC-2026-043',supplier:'Metales del Norte',date:'21 sep 2026',amount:68000,status:'En tránsito',item:'Perfil de aluminio 6063',ordered:'800 pzas',received:'0 pzas'},{id:'OC-2026-044',supplier:'Química Industrial MX',date:'23 sep 2026',amount:31000,status:'Emitida',item:'Adhesivo estructural A2',ordered:'100 L',received:'0 L'}];
const suppliers=[['Polímeros del Centro','Resinas y compuestos','María González','compras@polimeros.example','5 días'],['Metales del Norte','Metales y perfiles','Carlos Méndez','ventas@metales.example','3 días'],['Química Industrial MX','Adhesivos industriales','Laura Pérez','contacto@quimica.example','7 días'],['Acabados Profesionales','Pinturas y acabados','José Ramírez','ventas@acabados.example','4 días']];
let route='overview',query='',warehouse='all'; const money=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0}).format(n);const num=n=>new Intl.NumberFormat('es-MX',{maximumFractionDigits:3}).format(n);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const el=id=>document.getElementById(id);const pill=(text,color='')=>`<span class="pill ${color}">${esc(text)}</span>`;
function status(p){return p.qty<p.min?pill('Stock bajo','amber'):p.expiry&&p.expiry<'2026-10-01'?pill('Por caducar','amber'):pill('Disponible')}
function filtered(){return inventory.filter(p=>(warehouse==='all'||p.warehouse===warehouse)&&`${p.name} ${p.sku} ${p.lot}`.toLowerCase().includes(query.toLowerCase()))}
function product(p){return `<div class="product"><span class="product-icon">${icon('box')}</span><div><strong>${esc(p.name)}</strong><small>${p.sku} · ${p.kind}</small></div></div>`}
function header(title,sub,action='movement'){return `<div class="page-head"><div><p class="eyebrow">CENTRO DE CONTROL</p><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="head-actions"><span class="button date">${icon('calendar')}18 sep 2026</span>${action?`<button class="button primary" data-action="${action}">${icon('plus')}${action==='waste'?'Registrar merma':action==='purchase'?'Nueva orden':'Nuevo movimiento'}</button>`:''}</div></div>`}
function metrics(){const total=inventory.reduce((a,p)=>a+p.qty*p.cost,0);return `<div class="metrics">${[['Valor del inventario',money(total),'<span class="positive">MXN</span> · costo operativo','box'],['Artículos activos',String(inventory.length),'En 3 almacenes','layers'],['Lotes por caducar','2','<span class="warn">Dentro de los próximos 15 días</span>','clock'],['Mermas registradas',money(wastes.reduce((a,w)=>a+w.qty*inventory.find(p=>p.id===w.item).cost,0)),`${wastes.length} registros · septiembre`,'waste']].map(([label,value,note,i])=>`<div class="metric"><div class="metric-top">${label}<span class="metric-icon">${icon(i)}</span></div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`).join('')}</div>`}
function chart(){return `<section class="panel"><div class="panel-head"><div><h2>Actividad de inventario</h2><p>Operaciones registradas · últimos 7 días</p></div><div class="legend"><span><i></i>Entradas</span><span><i></i>Salidas</span></div></div><div class="chart-wrap"><div class="chart" role="img" aria-label="Actividad ilustrativa del 12 al 18 de septiembre: 94 entradas y 65 salidas"><div class="axis"><span>24</span><span>18</span><span>12</span><span>6</span><span>0</span></div><div class="bars">${[[10,7],[16,11],[8,5],[19,13],[12,8],[15,12],[14,9]].map(([a,b],i)=>`<div class="bar-group"><div class="bar" style="height:${a/24*100}%" title="${a} entradas"></div><div class="bar light" style="height:${b/24*100}%" title="${b} salidas"></div><span class="bar-label">${12+i} sep</span></div>`).join('')}</div></div><div class="chart-note"><strong>159 operaciones</strong> en el periodo <span style="float:right">Serie ilustrativa</span></div></div></section>`}
function alerts(){return `<section class="panel"><div class="panel-head"><h2>Requieren tu atención</h2><span class="alert-count">3 alertas</span></div><div class="alert-list">${[[4,'Caduca en 4 días',`${num(inventory[3].qty)} L disponibles · LT-2026-065`],[1,'Caduca en 7 días',`${num(inventory[0].qty)} kg disponibles · LT-2026-084`],[4,'Por debajo del stock mínimo','Adhesivo A2 · mínimo 50 L']].map(([id,title,desc])=>`<div class="alert-row"><span class="alert-icon">${icon('waste')}</span><div><strong>${title}</strong><p>${desc}</p><button class="button text" data-detail="${id}" style="font-size:12px">Revisar lote ${icon('arrow')}</button></div></div>`).join('')}</div></section>`}
function toolbar(){return `<div class="toolbar"><label class="searchbox">${icon('search')}<input id="search" aria-label="Buscar artículo, SKU o lote" placeholder="Buscar artículo, SKU o lote…" value="${esc(query)}"></label><select class="filter" id="warehouse" aria-label="Filtrar almacén"><option value="all">Todos los almacenes</option>${[...new Set(inventory.map(p=>p.warehouse))].map(w=>`<option ${warehouse===w?'selected':''}>${w}</option>`).join('')}</select><span class="result-count" id="result-count">${filtered().length} artículos</span></div>`}
function inventoryRows(){return filtered().map(p=>`<tr><td>${product(p)}</td><td>${p.lot}</td><td>${p.warehouse}</td><td><strong>${num(p.qty)}</strong> <span style="color:#849086">${p.unit}</span></td><td>${status(p)}</td><td><button class="row-link" data-detail="${p.id}" aria-label="Ver ${esc(p.name)}">↗</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No hay artículos que coincidan con tu búsqueda.</td></tr>'}
function inventoryPanel(){return `<section class="panel"><div class="panel-head"><div><h2>Inventario disponible</h2><p>Existencias por artículo, lote y almacén</p></div><button class="button text" data-action="export">${icon('download')}Exportar</button></div>${toolbar()}<div class="table-scroll"><table><thead><tr><th>Artículo</th><th>Lote</th><th>Almacén</th><th>Existencia</th><th>Estado</th><th></th></tr></thead><tbody id="inventory-rows">${inventoryRows()}</tbody></table></div><div class="table-foot"><span>Valores expresados en la unidad base de cada artículo</span><span>Actualizado en esta sesión</span></div></section>`}
function tablePanel(headers,rows){return `<section class="panel"><div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">Aún no hay registros.</td></tr>`}</tbody></table></div></section>`}
function render(){el('navigation').innerHTML=nav.map(([id,i,t])=>`<a href="#${id}" class="nav-item ${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(i)}${t}</a>`).join('');el('crumb').textContent=nav.find(n=>n[0]===route)[2];let html='';if(route==='overview')html=header('Resumen de operación','Todo lo que necesitas saber de tu inventario, en un solo lugar.')+metrics()+`<div class="overview-grid">${chart()}${alerts()}</div>`+inventoryPanel();if(route==='inventory')html=header('Inventario','Visibilidad de tus materiales y productos, almacén por almacén.')+metrics()+inventoryPanel();if(route==='lots')html=header('Lotes y trazabilidad','Consulta el origen, la ubicación y el recorrido de cada lote.',null)+tablePanel(['Lote / artículo','Almacén','Caducidad','Estado','Trazabilidad'],inventory.map(p=>`<tr><td><strong>${p.lot}</strong><p class="subtitle">${p.name}</p></td><td>${p.warehouse}</td><td>${p.expiry||'No aplica'}</td><td>${status(p)}</td><td><button class="button text" data-detail="${p.id}">Ver recorrido ${icon('arrow')}</button></td></tr>`).join(''));if(route==='purchases')html=header('Órdenes de compra','Gestiona el abastecimiento y da seguimiento a tus recepciones.','purchase')+tablePanel(['Orden','Proveedor','Entrega esperada','Total MXN','Estado',''],purchases.map((p,i)=>`<tr><td><strong>${p.id}</strong></td><td>${esc(p.supplier)}</td><td>${p.date}</td><td>${money(p.amount)}</td><td>${pill(p.status,p.status==='Recepción parcial'?'amber':'gray')}</td><td><button class="button text" data-purchase="${i}">Ver orden ↗</button></td></tr>`).join(''));if(route==='movements')html=header('Movimientos','Historial de entradas y salidas por artículo y lote.')+tablePanel(['Tipo','Artículo','Cantidad','Referencia','Fecha'],movements.map(m=>{const p=inventory.find(p=>p.id===m.item);return `<tr><td>${pill(m.type,m.type==='Entrada'?'':'amber')}</td><td>${product(p)}</td><td>${m.type==='Entrada'?'+':'−'}${num(m.qty)} ${p.unit}</td><td>${esc(m.ref)}</td><td>${esc(m.date)}</td></tr>`}).join(''));if(route==='waste')html=header('Control de mermas','Identifica las pérdidas de almacenamiento y sus causas.','waste')+`<div class="value-banner">${icon('waste').replace('<svg','<svg width="30" height="30"')}<div><strong>${money(wastes.reduce((a,w)=>a+w.qty*inventory.find(p=>p.id===w.item).cost,0))}</strong><br><span>Costo operativo acumulado · ${wastes.length} registros · MXN</span></div></div>`+tablePanel(['Artículo','Pérdida','Causa','Costo operativo','Fecha'],wastes.map(w=>{const p=inventory.find(p=>p.id===w.item);return `<tr><td>${product(p)}</td><td>${num(w.qty)} ${p.unit}</td><td>${pill(w.cause,'amber')}</td><td>${money(w.qty*p.cost)}</td><td>${esc(w.date)}</td></tr>`}).join(''));if(route==='suppliers')html=header('Proveedores','Tu red de abastecimiento, organizada en un solo lugar.',null)+tablePanel(['Proveedor','Especialidad','Contacto','Plazo habitual'],suppliers.map(s=>`<tr><td><strong>${s[0]}</strong></td><td>${s[1]}</td><td>${s[2]}<p class="subtitle">${s[3]}</p></td><td>${s[4]}</td></tr>`).join(''));if(route==='warehouses')html=header('Almacenes','Distribución de existencias y valor operativo por ubicación.',null)+`<div class="warehouse-grid">${['Almacén central','Taller de producción','Producto terminado'].map((w,i)=>{const ps=inventory.filter(p=>p.warehouse===w);return `<section class="panel warehouse-card"><span class="metric-icon">${icon('warehouse')}</span><h2 style="margin-top:20px">${w}</h2><p>ALM-00${i+1} · ${ps.length} artículos</p><div class="warehouse-number">${money(ps.reduce((a,p)=>a+p.qty*p.cost,0))}</div><p>Valor de existencias · MXN</p><button class="button" data-warehouse="${w}">Consultar inventario ${icon('arrow')}</button></section>`}).join('')}</div>`;el('main').innerHTML=html;bindFilters()}
function bindFilters(){el('search')?.addEventListener('input',e=>{query=e.target.value;el('inventory-rows').innerHTML=inventoryRows();el('result-count').textContent=filtered().length+' artículos'});el('warehouse')?.addEventListener('change',e=>{warehouse=e.target.value;el('inventory-rows').innerHTML=inventoryRows();el('result-count').textContent=filtered().length+' artículos'})}
function toast(message){el('toast').textContent=message;el('toast').classList.add('visible');setTimeout(()=>el('toast').classList.remove('visible'),4000)}
function openModal(title,body){el('modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-close aria-label="Cerrar">×</button></div><div class="modal-body">${body}</div>`;el('modal').showModal()}
function detail(id){const p=inventory.find(p=>p.id===id);if(!p)return;openModal('Detalle y trazabilidad del lote',`${product(p)}<div class="detail-grid"><div><small>Lote</small><strong>${p.lot}</strong></div><div><small>Estado</small>${status(p)}</div><div><small>Existencia actual</small><strong>${num(p.qty)} ${p.unit}</strong></div><div><small>Caducidad</small><strong>${p.expiry||'No aplica'}</strong></div><div><small>Ubicación</small><strong>${p.warehouse}</strong></div><div><small>Origen</small><strong>${p.supplier}</strong></div></div><h3>Recorrido ilustrativo</h3><div class="timeline"><div>${p.kind==='Insumo'?'Recepción del proveedor':'Producción terminada'}<small>${p.supplier} · 12 sep 2026</small></div><div>Ingreso al almacén<small>${p.warehouse} · 12 sep 2026</small></div><div>Disponible para operación<small>${num(p.qty)} ${p.unit} · consulta actual</small></div></div><p class="note">La genealogía de producción y los documentos originales se conectarán mediante la API.</p>`)}
function movementForm(isWaste=false){openModal(isWaste?'Registrar merma de almacenamiento':'Nuevo movimiento',`<form id="operation-form"><div class="form-grid">${isWaste?'':`<label class="field full">Tipo de movimiento<select name="type"><option>Entrada</option><option>Salida</option></select></label>`}<label class="field full">Artículo y lote<select name="item">${inventory.map(p=>`<option value="${p.id}">${p.name} · ${p.lot}</option>`).join('')}</select></label><label class="field">Cantidad<input name="qty" type="number" min="0.001" step="0.001" required placeholder="0.000"></label><label class="field">Unidad y saldo<input id="unit-info" readonly></label>${isWaste?`<label class="field full">Causa<select name="cause"><option>Derrame</option><option>Caducidad</option><option>Daño de empaque</option><option>Daño en almacenamiento</option></select></label>`:`<label class="field full">Referencia<input name="reference" required maxlength="60" placeholder="OC, entrega o documento de referencia"></label>`}<label class="field full">Observaciones<input name="note" maxlength="200" placeholder="Describe el motivo de la operación"></label></div><p class="note">Demostración: el movimiento actualizará las existencias de esta sesión. No se envía a un servidor.</p><div class="modal-actions"><button type="button" class="button" data-close>Cancelar</button><button class="button primary" type="submit">Confirmar ${isWaste?'merma':'movimiento'}</button></div></form>`);const f=el('operation-form');const updateUnit=()=>{const p=inventory.find(p=>p.id===Number(f.elements.namedItem('item').value));el('unit-info').value=`${p.unit} · ${num(p.qty)} disponibles`;f.elements.qty.setCustomValidity('')};f.elements.namedItem('item').addEventListener('change',updateUnit);f.elements.qty.addEventListener('input',()=>f.elements.qty.setCustomValidity(''));updateUnit();f.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(f),p=inventory.find(p=>p.id===Number(data.get('item'))),qty=Number(data.get('qty')),type=isWaste?'Merma':data.get('type');if(!Number.isFinite(qty)||qty<=0)return;if(type!=='Entrada'&&qty>p.qty){f.elements.qty.setCustomValidity('La cantidad supera la existencia disponible.');f.elements.qty.reportValidity();return}p.qty=Math.round((p.qty+(type==='Entrada'?qty:-qty))*1000)/1000;const date='18 sep 2026 · sesión';movements.unshift({type,item:p.id,qty,date,ref:isWaste?'MER-'+String(wastes.length+1).padStart(4,'0'):data.get('reference'),reason:data.get('note')});if(isWaste)wastes.unshift({item:p.id,qty,cause:data.get('cause'),date,note:data.get('note')});el('modal').close();render();toast(isWaste?'Merma registrada. Existencias actualizadas.':'Movimiento confirmado. Existencias actualizadas.')})}
function purchaseForm(){openModal('Nueva orden de compra',`<form id="purchase-form"><div class="form-grid"><label class="field full">Proveedor<select name="supplier">${suppliers.map(s=>`<option>${s[0]}</option>`).join('')}</select></label><label class="field full">Artículo<select name="item">${inventory.filter(p=>p.kind==='Insumo').map(p=>`<option value="${p.id}">${p.name} (${p.unit})</option>`).join('')}</select></label><label class="field">Cantidad<input name="qty" type="number" required min="0.001" step="0.001"></label><label class="field">Precio unitario MXN<input name="price" type="number" required min="0.01" step="0.01"></label><label class="field full">Entrega esperada<input name="date" type="date" required min="2026-09-18"></label></div><p class="note">Se creará un borrador en esta sesión. No se envía al proveedor.</p><div class="modal-actions"><button type="button" class="button" data-close>Cancelar</button><button type="submit" class="button primary">Crear borrador</button></div></form>`);el('purchase-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target),p=inventory.find(p=>p.id===Number(d.get('item')));purchases.unshift({id:'OC-2026-'+String(45+purchases.length-3).padStart(3,'0'),supplier:d.get('supplier'),date:d.get('date'),amount:Number(d.get('qty'))*Number(d.get('price')),status:'Borrador',item:p.name,ordered:`${d.get('qty')} ${p.unit}`,received:`0 ${p.unit}`});el('modal').close();render();toast('Borrador de compra creado.')})}
function exportInventory(){const csv=[['SKU','Artículo','Lote','Almacén','Cantidad','Unidad'],...filtered().map(p=>[p.sku,p.name,p.lot,p.warehouse,p.qty,p.unit])].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='nexo-inventario.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Inventario exportado.')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close'))el('modal').close();if(b.dataset.detail)detail(Number(b.dataset.detail));if(b.dataset.action==='movement')movementForm();if(b.dataset.action==='waste')movementForm(true);if(b.dataset.action==='purchase')purchaseForm();if(b.dataset.action==='export')exportInventory();if(b.dataset.purchase!==undefined){const p=purchases[Number(b.dataset.purchase)];openModal(p.id,`<p>${esc(p.supplier)}</p><div class="detail-grid"><div><small>Artículo</small><strong>${esc(p.item)}</strong></div><div><small>Estado</small>${pill(p.status,'gray')}</div><div><small>Pedido</small><strong>${esc(p.ordered)}</strong></div><div><small>Recibido</small><strong>${esc(p.received)}</strong></div><div><small>Total MXN</small><strong>${money(p.amount)}</strong></div><div><small>Entrega esperada</small><strong>${esc(p.date)}</strong></div></div><p class="note">El flujo de recepción contra orden se conectará al backend de compras.</p>`)}if(b.dataset.warehouse){warehouse=b.dataset.warehouse;query='';location.hash='inventory'}});
el('menu').addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'));document.querySelector('.sidebar').addEventListener('click',e=>{if(e.target.closest('a'))document.querySelector('.sidebar').classList.remove('open')});el('modal').addEventListener('click',e=>{if(e.target===el('modal'))el('modal').close()});function navigate(){route=nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'overview';render()}window.addEventListener('hashchange',navigate);navigate();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'filter_inventory',title:'Filtrar inventario',description:'Abre el inventario y filtra los artículos de demostración por nombre, SKU o lote.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.query!=='string'||Object.keys(input).some(k=>k!=='query'))throw Error('Se requiere una consulta de texto.');query=input.query;warehouse='all';route='inventory';history.replaceState(null,'','#inventory');render();return {count:filtered().length,items:filtered().map(p=>({sku:p.sku,name:p.name,quantity:p.qty,unit:p.unit}))}}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
